package com.mytransitgps.modules.ciq.collector;
import com.mytransitgps.modules.ciq.client.LtaRoadOpeningsClient;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.domain.RoadOpeningRecord;import com.mytransitgps.modules.ciq.parser.RoadOpeningsParser;import com.mytransitgps.modules.ciq.persistence.*;import com.mytransitgps.modules.ciq.quality.RoadOpeningsValidator;import com.mytransitgps.modules.ciq.storage.*;import com.mytransitgps.platform.collection.*;import org.slf4j.*;
/** API08 独立 Collector。 */
public class CiqRoadOpeningsCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqRoadOpeningsCollector.class);private final CiqPagedJsonCollectorSupport<RoadOpeningRecord> support;public CiqRoadOpeningsCollector(LtaRoadOpeningsClient client,CiqProperties p,CiqJsonStorageService storage,RoadOpeningsParser parser,RoadOpeningsValidator validator,RoadOpeningsPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API08",CiqApiCode.API08,CollectorCode.CIQ_ROAD_OPENINGS,client,p,p.getCollectors().getRoadOpenings(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_ROAD_OPENINGS;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
